1	package search
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"net/http"
10		"net/url"
11		"strconv"
12		"strings"
13		"time"
14	
15		"github.com/entireio/cli/cmd/entire/cli/versioninfo"
16	)
17	
18	const apiTimeout = 30 * time.Second
19	
20	// DefaultServiceURL is the production search service URL.
21	const DefaultServiceURL = "https://entire.io"
22	
23	// WildcardQuery is the query string used when only filters are provided (no search terms).
24	const WildcardQuery = "*"
25	
26	// AllReposFilter is the inline repo filter value that disables repo scoping.
27	const AllReposFilter = "*"
28	
29	// Result type constants.
30	const (
31		TypeCheckpoint = "checkpoint"
32		TypeCommit     = "commit"
33		TypeSession    = "session"
34	)
35	
36	// MaxLimit is the maximum number of results the search API will return per request.
37	const MaxLimit = 200
38	
39	// DefaultLimit is the default number of results to fetch per request, matching the UI.
40	const DefaultLimit = 100
41	
42	// Meta contains search ranking metadata for a result.
43	type Meta struct {
44		MatchType string   `json:"matchType"`
45		Score     float64  `json:"score"`
46		Tier      *int     `json:"tier,omitempty"`
47		Snippet   string   `json:"snippet,omitempty"`
48		Summary   string   `json:"summary,omitempty"`
49		BM25Score *float64 `json:"bm25Score,omitempty"`
50		ANNScore  *float64 `json:"annScore,omitempty"`
51	}
52	
53	// CheckpointResult represents a checkpoint returned by the search service.
54	type CheckpointResult struct {
55		ID             string   `json:"id"`
56		Prompt         string   `json:"prompt"`
57		CommitMessage  *string  `json:"commitMessage"`
58		CommitSubject  *string  `json:"commitSubject"`
59		CommitSHA      *string  `json:"commitSha"`
60		Branch         string   `json:"branch"`
61		Org            string   `json:"org"`
62		Repo           string   `json:"repo"`
63		Author         string   `json:"author"`
64		AuthorUsername *string  `json:"authorUsername"`
65		CreatedAt      string   `json:"createdAt"`
66		FilesTouched   []string `json:"filesTouched"`
67	}
68	
69	// CommitResult represents a commit returned by the search service.
70	type CommitResult struct {
71		ID             string  `json:"id"`
72		CommitSHA      string  `json:"commitSha"`
73		CommitMessage  string  `json:"commitMessage"`
74		CommitSubject  string  `json:"commitSubject"`
75		Branch         string  `json:"branch"`
76		Org            string  `json:"org"`
77		Repo           string  `json:"repo"`
78		Author         string  `json:"author"`
79		AuthorUsername *string `json:"authorUsername"`
80		CreatedAt      string  `json:"createdAt"`
81		Additions      int     `json:"additions"`
82		Deletions      int     `json:"deletions"`
83		FilesChanged   int     `json:"filesChanged"`
84		HTMLUrl        *string `json:"htmlUrl"`
85	}
86	
87	// SessionResult represents a session returned by the search service.
88	type SessionResult struct {
89		SessionID      string  `json:"sessionId"`
90		DisplayName    string  `json:"displayName"`
91		Prompt         *string `json:"prompt"`
92		Agent          *string `json:"agent"`
93		Model          *string `json:"model"`
94		StepCount      int     `json:"stepCount"`
95		Org            string  `json:"org"`
96		Repo           string  `json:"repo"`
97		Branch         *string `json:"branch"`
98		AuthorUsername *string `json:"authorUsername"`
99		CreatedAt      string  `json:"createdAt"`
100	}
101	
102	// Result wraps a search result with its type and ranking metadata.
103	// Exactly one of Checkpoint, Commit, or Session is non-nil based on Type.
104	type Result struct {
105		Type       string            `json:"-"`
106		Meta       Meta              `json:"-"`
107		Checkpoint *CheckpointResult `json:"-"`
108		Commit     *CommitResult     `json:"-"`
109		Session    *SessionResult    `json:"-"`
110	
111		// rawData preserves the original JSON for unknown types (repo, pr)
112		rawData json.RawMessage
113	}
114	
115	// resultJSON is the wire format for JSON marshaling/unmarshaling.
116	type resultJSON struct {
117		Type string          `json:"type"`
118		Data json.RawMessage `json:"data"`
119		Meta Meta            `json:"searchMeta"`
120	}
121	
122	// MarshalJSON implements custom JSON marshaling to produce the API wire format.
123	func (r *Result) MarshalJSON() ([]byte, error) {
124		var data any
125		switch r.Type {
126		case TypeCheckpoint:
127			data = r.Checkpoint
128		case TypeCommit:
129			data = r.Commit
130		case TypeSession:
131			data = r.Session
132		default:
133			data = r.rawData
134		}
135		raw, err := json.Marshal(data)
136		if err != nil {
137			return nil, fmt.Errorf("marshaling result data: %w", err)
138		}
139		out, err := json.Marshal(resultJSON{
140			Type: r.Type,
141			Data: raw,
142			Meta: r.Meta,
143		})
144		if err != nil {
145			return nil, fmt.Errorf("marshaling result: %w", err)
146		}
147		return out, nil
148	}
149	
150	// UnmarshalJSON implements custom JSON unmarshaling to parse typed data.
151	func (r *Result) UnmarshalJSON(b []byte) error {
152		var raw resultJSON
153		if err := json.Unmarshal(b, &raw); err != nil {
154			return fmt.Errorf("unmarshaling result: %w", err)
155		}
156		r.Type = raw.Type
157		r.Meta = raw.Meta
158		r.rawData = raw.Data
159		// Clear any previously-decoded payloads so a reused Result keeps the
160		// "exactly one typed pointer is non-nil" invariant.
161		r.Checkpoint, r.Commit, r.Session = nil, nil, nil
162	
163		switch raw.Type {
164		case TypeCheckpoint:
165			var d CheckpointResult
166			if err := json.Unmarshal(raw.Data, &d); err != nil {
167				return fmt.Errorf("unmarshaling checkpoint data: %w", err)
168			}
169			r.Checkpoint = &d
170		case TypeCommit:
171			var d CommitResult
172			if err := json.Unmarshal(raw.Data, &d); err != nil {
173				return fmt.Errorf("unmarshaling commit data: %w", err)
174			}
175			r.Commit = &d
176		case TypeSession:
177			var d SessionResult
178			if err := json.Unmarshal(raw.Data, &d); err != nil {
179				return fmt.Errorf("unmarshaling session data: %w", err)
180			}
181			r.Session = &d
182		}
183		return nil
184	}
185	
186	// resultField dispatches to the accessor matching the result's type, guarding
187	// against a nil payload (returns "" for nil or unknown types like repo/pr).
188	func resultField(r *Result, fromCheckpoint func(*CheckpointResult) string, fromCommit func(*CommitResult) string, fromSession func(*SessionResult) string) string {
189		switch r.Type {
190		case TypeCheckpoint:
191			if r.Checkpoint != nil {
192				return fromCheckpoint(r.Checkpoint)
193			}
194		case TypeCommit:
195			if r.Commit != nil {
196				return fromCommit(r.Commit)
197			}
198		case TypeSession:
199			if r.Session != nil {
200				return fromSession(r.Session)
201			}
202		}
203		return ""
204	}
205	
206	// ResultOrg returns the org for any result type.
207	func (r *Result) ResultOrg() string {
208		return resultField(r,
209			func(c *CheckpointResult) string { return c.Org },
210			func(c *CommitResult) string { return c.Org },
211			func(s *SessionResult) string { return s.Org })
212	}
213	
214	// ResultRepo returns the repo for any result type.
215	func (r *Result) ResultRepo() string {
216		return resultField(r,
217			func(c *CheckpointResult) string { return c.Repo },
218			func(c *CommitResult) string { return c.Repo },
219			func(s *SessionResult) string { return s.Repo })
220	}
221	
222	// ResultBranch returns the branch for any result type.
223	func (r *Result) ResultBranch() string {
224		return resultField(r,
225			func(c *CheckpointResult) string { return c.Branch },
226			func(c *CommitResult) string { return c.Branch },
227			func(s *SessionResult) string {
228				if s.Branch != nil {
229					return *s.Branch
230				}
231				return ""
232			})
233	}
234	
235	// ResultCreatedAt returns the createdAt for any result type.
236	func (r *Result) ResultCreatedAt() string {
237		return resultField(r,
238			func(c *CheckpointResult) string { return c.CreatedAt },
239			func(c *CommitResult) string { return c.CreatedAt },
240			func(s *SessionResult) string { return s.CreatedAt })
241	}
242	
243	// ResultAuthor returns the display author for any result type.
244	func (r *Result) ResultAuthor() string {
245		return resultField(r,
246			func(c *CheckpointResult) string {
247				if c.AuthorUsername != nil && *c.AuthorUsername != "" {
248					return *c.AuthorUsername
249				}
250				return c.Author
251			},
252			func(c *CommitResult) string {
253				if c.AuthorUsername != nil && *c.AuthorUsername != "" {
254					return *c.AuthorUsername
255				}
256				return c.Author
257			},
258			func(s *SessionResult) string {
259				if s.AuthorUsername != nil {
260					return *s.AuthorUsername
261				}
262				return ""
263			})
264	}
265	
266	// ResultID returns the primary ID for any result type.
267	func (r *Result) ResultID() string {
268		return resultField(r,
269			func(c *CheckpointResult) string { return c.ID },
270			func(c *CommitResult) string { return c.CommitSHA },
271			func(s *SessionResult) string { return s.SessionID })
272	}
273	
274	// ResultTitle returns the primary display text for any result type.
275	func (r *Result) ResultTitle() string {
276		return resultField(r,
277			func(c *CheckpointResult) string {
278				// Prefer the commit title over the prompt; fall back to the prompt
279				// for uncommitted checkpoints. The full prompt remains in the detail view.
280				if c.CommitSubject != nil && *c.CommitSubject != "" {
281					return *c.CommitSubject
282				}
283				if c.CommitMessage != nil && *c.CommitMessage != "" {
284					return *c.CommitMessage
285				}
286				return c.Prompt
287			},
288			func(c *CommitResult) string {
289				if c.CommitSubject != "" {
290					return c.CommitSubject
291				}
292				return c.CommitMessage
293			},
294			func(s *SessionResult) string { return s.DisplayName })
295	}
296	
297	// TypeCounts holds per-type result counts.
298	type TypeCounts struct {
299		Repos       int `json:"repos"`
300		Checkpoints int `json:"checkpoints"`
301		Commits     int `json:"commits"`
302		PRs         int `json:"prs"`
303		Sessions    int `json:"sessions"`
304	}
305	
306	// Timing holds search performance timing data.
307	type Timing struct {
308		TotalMs            *float64 `json:"total_ms"`
309		KeywordMs          *float64 `json:"keyword_ms"`
310		EmbeddingMs        *float64 `json:"embedding_ms"`
311		VectorMs           *float64 `json:"vector_ms"`
312		RerankMs           *float64 `json:"rerank_ms"`
313		FanoutMs           *float64 `json:"fanout_ms"`
314		SessionHydrationMs *float64 `json:"session_hydration_ms"`
315	}
316	
317	// Response is the search service response.
318	type Response struct {
319		Results  []Result    `json:"results"`
320		Total    int         `json:"total"`
321		Page     int         `json:"page"`
322		Error    string      `json:"error,omitempty"`
323		Timing   *Timing     `json:"timing,omitempty"`
324		Reranked *bool       `json:"reranked,omitempty"`
325		Counts   *TypeCounts `json:"counts,omitempty"`
326	}
327	
328	// Config holds the configuration for a search request.
329	type Config struct {
330		ServiceURL  string // Base URL of the search service
331		GitHubToken string
332		Owner       string
333		Repo        string
334		Repos       []string
335		AllRepos    bool // When true, search all accessible repos (no repo scoping)
336		Query       string
337		Limit       int
338		Author      string // Filter by author name
339		Date        string // Filter by time period: "week" or "month"
340		Branch      string // Filter by branch name
341		Page        int    // 1-based page number (0 means omit, API defaults to 1)
342	}
343	
344	// HasFilters reports whether any filter fields are set on the config.
345	func (c Config) HasFilters() bool {
346		return c.Author != "" || c.Date != "" || c.Branch != "" || len(c.Repos) > 0 || c.AllRepos
347	}
348	
349	// ParsedInput holds the parsed query and optional filters extracted from search input.
350	type ParsedInput struct {
351		Query  string
352		Author string
353		Date   string
354		Branch string
355		Repos  []string
356	}
357	
358	// ParseSearchInput extracts filter prefixes from raw input.
359	// Supports quoted values for single-value filters, for example: author:"alice smith".
360	// Remaining tokens become the query.
361	func ParseSearchInput(raw string) ParsedInput {
362		var p ParsedInput
363		var queryParts []string
364	
365		tokens := tokenizeInput(raw)
366		for _, tok := range tokens {
367			switch {
368			case strings.HasPrefix(tok, "author:"):
369				p.Author = strings.Trim(tok[len("author:"):], "\"")
370			case strings.HasPrefix(tok, "date:"):
371				p.Date = strings.Trim(tok[len("date:"):], "\"")
372			case strings.HasPrefix(tok, "branch:"):
373				p.Branch = strings.Trim(tok[len("branch:"):], "\"")
374			case strings.HasPrefix(tok, "repo:"):
375				p.Repos = appendUnique(p.Repos, parseListFilter(strings.TrimPrefix(tok, "repo:"))...)
376			default:
377				queryParts = append(queryParts, tok)
378			}
379		}
380	
381		p.Query = strings.Join(queryParts, " ")
382		return p
383	}
384	
385	// tokenizeInput splits input on whitespace but respects quoted values after filter prefixes.
386	// Example: `author:"alice smith" fix bug` → ["author:\"alice smith\"", "fix", "bug"]
387	func tokenizeInput(s string) []string {
388		var tokens []string
389		i := 0
390		s = strings.TrimSpace(s)
391		for i < len(s) {
392			// Skip whitespace
393			for i < len(s) && s[i] == ' ' {
394				i++
395			}
396			if i >= len(s) {
397				break
398			}
399	
400			start := i
401	
402			// Look ahead: is this a prefix:"quoted" token?
403			if colonIdx := strings.Index(s[i:], ":\""); colonIdx >= 0 && !strings.Contains(s[i:i+colonIdx], " ") {
404				// Found prefix:" — scan to closing quote
405				quoteStart := i + colonIdx + 2
406				endQuote := strings.IndexByte(s[quoteStart:], '"')
407				if endQuote >= 0 {
408					i = quoteStart + endQuote + 1
409					tokens = append(tokens, s[start:i])
410					continue
411				}
412			}
413	
414			// Regular token: advance to next space
415			for i < len(s) && s[i] != ' ' {
416				i++
417			}
418			tokens = append(tokens, s[start:i])
419		}
420		return tokens
421	}
422	
423	func parseListFilter(raw string) []string {
424		if raw == "" {
425			return nil
426		}
427	
428		parts := strings.Split(raw, ",")
429		values := make([]string, 0, len(parts))
430		for _, part := range parts {
431			value := strings.Trim(strings.TrimSpace(part), "\"")
432			if value == "" {
433				continue
434			}
435			values = append(values, value)
436		}
437	
438		return values
439	}
440	
441	// ValidateRepoFilters ensures repo filters match backend semantics.
442	func ValidateRepoFilters(repos []string) error {
443		if len(repos) > 1 {
444			return errors.New("only one explicit repo filter is currently supported")
445		}
446		if len(repos) == 1 && !isValidRepoFilter(repos[0]) {
447			return fmt.Errorf(
448				"invalid repo filter %q: expected owner/name or *; if you meant all repos, quote the asterisk: --repo '*'",
449				repos[0],
450			)
451		}
452		return nil
453	}
454	
455	func isValidRepoFilter(repo string) bool {
456		if repo == AllReposFilter {
457			return true
458		}
459		if strings.Contains(repo, " ") {
460			return false
461		}
462		parts := strings.Split(repo, "/")
463		return len(parts) == 2 && parts[0] != "" && parts[1] != ""
464	}
465	
466	func appendUnique(existing []string, values ...string) []string {
467		if len(values) == 0 {
468			return existing
469		}
470	
471		seen := make(map[string]struct{}, len(existing)+len(values))
472		for _, value := range existing {
473			seen[value] = struct{}{}
474		}
475		for _, value := range values {
476			if _, ok := seen[value]; ok {
477				continue
478			}
479			seen[value] = struct{}{}
480			existing = append(existing, value)
481		}
482	
483		return existing
484	}
485	
486	var httpClient = &http.Client{}
487	
488	// Search calls the search service to perform a hybrid search.
489	func Search(ctx context.Context, cfg Config) (*Response, error) {
490		ctx, cancel := context.WithTimeout(ctx, apiTimeout)
491		defer cancel()
492	
493		serviceURL := cfg.ServiceURL
494		if serviceURL == "" {
495			serviceURL = DefaultServiceURL
496		}
497	
498		u, err := url.Parse(serviceURL)
499		if err != nil {
500			return nil, fmt.Errorf("parsing service URL: %w", err)
501		}
502		u.Path = "/search/v1/search"
503	
504		q := u.Query()
505		q.Set("q", cfg.Query)
506		if err := ValidateRepoFilters(cfg.Repos); err != nil {
507			return nil, err
508		}
509		allRepos := cfg.AllRepos || (len(cfg.Repos) == 1 && cfg.Repos[0] == AllReposFilter)
510		hasExplicitRepo := false
511		for _, repo := range cfg.Repos {
512			if repo != AllReposFilter {
513				hasExplicitRepo = true
514				break
515			}
516		}
517		switch {
518		case hasExplicitRepo:
519			// An explicit owner/name filter always scopes the search, even when
520			// --all-repos is also set (the more specific filter wins).
521			for _, repo := range cfg.Repos {
522				if repo != AllReposFilter {
523					q.Add("repo", repo)
524				}
525			}
526		case allRepos:
527			// No repo scoping — search every accessible repo.
528		case cfg.Owner != "" && cfg.Repo != "":
529			q.Set("repo", cfg.Owner+"/"+cfg.Repo)
530		}
531		// Don't set types — let the API return all types (checkpoints, commits, sessions, etc.)
532		if cfg.Limit > 0 {
533			q.Set("limit", strconv.Itoa(cfg.Limit))
534		}
535		if cfg.Author != "" {
536			q.Set("author", cfg.Author)
537		}
538		if cfg.Date != "" {
539			q.Set("date", cfg.Date)
540		}
541		if cfg.Branch != "" {
542			q.Set("branch", cfg.Branch)
543		}
544		if cfg.Page > 0 {
545			q.Set("page", strconv.Itoa(cfg.Page))
546		}
547		u.RawQuery = q.Encode()
548	
549		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
550		if err != nil {
551			return nil, fmt.Errorf("creating request: %w", err)
552		}
553		req.Header.Set("Authorization", "Bearer "+cfg.GitHubToken)
554		req.Header.Set("User-Agent", versioninfo.UserAgent())
555	
556		resp, err := httpClient.Do(req)
557		if err != nil {
558			return nil, fmt.Errorf("calling search service: %w", err)
559		}
560		defer resp.Body.Close()
561	
562		body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
563		if err != nil {
564			return nil, fmt.Errorf("reading response: %w", err)
565		}
566	
567		if resp.StatusCode != http.StatusOK {
568			var errResp struct {
569				Error string `json:"error"`
570			}
571			if json.Unmarshal(body, &errResp) == nil && errResp.Error != "" {
572				return nil, fmt.Errorf("search service error (%d): %s", resp.StatusCode, errResp.Error)
573			}
574			return nil, fmt.Errorf("search service returned %d: %s", resp.StatusCode, string(body))
575		}
576	
577		var result Response
578		if err := json.Unmarshal(body, &result); err != nil {
579			return nil, fmt.Errorf("unexpected response from search service: %s", string(body))
580		}
581	
582		if result.Error != "" {
583			return nil, fmt.Errorf("search service error: %s", result.Error)
584		}
585	
586		return &result, nil
587	}
588

