// and the results UI is unchanged. `repo` is resolved slug → ULID before forwarding.
const FORWARDED_PARAMS = [
  "q",
  "types",
  "branch",
  "author",
  "date",
  "page",
  "limit",
  "mode",
  "filter_type",
] as const

const UPSTREAM_TIMEOUT_MS = 30_000

/**
 * Resolve an `owner/repo` (or `gh/owner/repo`) slug to its storage ULID using the
 * caller's read-filtered repo index — the same source code-search (`/stream`) and
 * `repos-stream` use. query-serve keys on the ULID, not the slug. Returns:
 *  - `{ kind: "ulid", ulid }` on a match,
 *  - `{ kind: "not_found" }` when the repo is absent from a COMPLETE index (no access),
 *  - `{ kind: "unavailable" }` when the index call fails or the index was capped
 *    (`truncated`) and the repo wasn't in the returned page — we can't conclude
 *    no-access from a partial list, so the caller should treat it as retryable.
 */
async function resolveRepoUlid(
  coreBaseUrl: string,
  loginJwt: string,
  slug: string,
): Promise<{ kind: "ulid"; ulid: string } | { kind: "not_found" } | { kind: "unavailable" }> {
  let index
  try {
    index = await listReposIndex({ coreBaseUrl, loginJwt })
  } catch {
    return { kind: "unavailable" }
  }

  const match = matchRepoInIndex(index.repos, slug)
  if (match) return { kind: "ulid", ulid: match.id }

  // No match. If core capped the index we can't distinguish "no access" from
  // "fell outside the returned page", so avoid a misleading 404 — treat it as
  // retryable instead of asserting the repo doesn't exist for this caller.
  return index.truncated ? { kind: "unavailable" } : { kind: "not_found" }
}

// ---------------------------------------------------------------------------
// GET /search — per-repo v4 semantic search via the entire-api gateway.
//
// The v4 path for the per-repo `semantic-search-v4` rollout (ENT-1014). The
// frontend routes a repo here only when it is in the flag allowlist; every
// other repo keeps hitting the Cloudflare worker directly (v3, unchanged).
//
// Resolves the caller's session cookie → entire-core jurisdictional JWT (RFC 8693
// exchange, whose audience matches query-serve's jurisdictional JWT_AUDIENCE) and
// resolves the repo slug → storage ULID, then forwards to entire-api
// `/semantic-search`. entire-search scopes results via SpiceDB `repo#list` authz.
// On any failure we return an error for this search — we do NOT fall back to v3,
// so v4 problems stay visible during rollout.
// ---------------------------------------------------------------------------
searchRoutes.get(
  "/",
  describeRoute({
    tags: ["Search"],
    summary: "Semantic search via the entire-api gateway (v4)",
    description:
      "Proxies semantic search to entire-search through the entire-api gateway, " +
      "resolving the session cookie to a jurisdictional JWT and the repo slug to " +
      "a storage ULID. Response shape matches the legacy Cloudflare search worker.",
    responses: {
      200: { description: "Search results" },
      400: { description: "Missing q or repo" },
      401: { description: "Unable to resolve authentication token (re-auth required)" },
      404: { description: "Repo not found or not accessible" },
      502: { description: "Upstream search error or repo could not be resolved" },
      503: { description: "Search is not configured" },
    },
  }),
  async (c) => {
    if (!c.env.ENTIRE_API_SEARCH_BASE_URL) {
      return c.json({ error: "Search is not configured" }, 503)
    }

    // v4 is a per-repo gate — a repo is always required. Trim so a
    // whitespace-only value is rejected here with 400 rather than slipping
    // through to slug resolution and surfacing as a misleading 404.
    const repoInput = c.req.query("repo")?.trim()
    if (!repoInput) {
      return c.json({ error: "repo is required" }, 400)
    }

    // A blank query has nothing to search. The frontend always sends a
    // non-empty q, but this route is directly callable by CLI/bearer clients,
    // so reject it here rather than forwarding an empty search upstream.
    if (!c.req.query("q")?.trim()) {
      return c.json({ error: "q is required" }, 400)
    }

    const sessionToken = getCookie(c, "session")
    const isBearerCaller = c.req.header("Authorization")?.startsWith("Bearer ")
    const isSessionCaller = Boolean(sessionToken) && !isBearerCaller

    // Browser (session) callers need their login JWT twice: once to mint the
    // jurisdictional bearer, once to resolve the repo slug → ULID. Resolve it a
    // single time here and thread it into both. Only a genuine credential
    // failure (`reauth`) is a 401; a missing/failed core is a 5xx, not an auth
    // error (mapping it to 401 would wrongly signal "session expired").
    let loginJwt: string | undefined
    let coreBaseUrl: string | undefined
    if (isSessionCaller) {
      const coreConfig = getCoreAuthConfig(c.env)
      if (!coreConfig) {
        return c.json({ error: "Search is not configured" }, 503)
      }
      coreBaseUrl = coreConfig.baseUrl
      const loginResult = await getValidLoginJwt(
        {
          kv: c.env.ENTIRE_CACHE,
          secret: c.env.ENCRYPTION_KEY,
          cfg: {
            coreBaseUrl: coreConfig.baseUrl,
            clientId: coreConfig.clientId,
            clientSecret: coreConfig.clientSecret,
          },
        },
        sessionToken as string,
      )
      if (loginResult.kind === "reauth") {
        return c.json({ error: "Unable to resolve authentication token for search" }, 401)
      }
      if (loginResult.kind !== "jwt") {
        return c.json({ error: "Unable to resolve repo for search" }, 502)
      }
      loginJwt = loginResult.jwt
    }

    // Bearer minting and repo slug → ULID resolution both depend only on the
    // login JWT and are otherwise independent, so run them concurrently to save
    // a round-trip on the browser search path. CLI/bearer callers resolve no
    // login JWT and pass a ULID, so their repo resolution is skipped (null).
    const [bearerToken, resolvedRepo] = await Promise.all([
      resolveSearchBearerToken(c, { loginJwt }),
      loginJwt && coreBaseUrl ? resolveRepoUlid(coreBaseUrl, loginJwt, repoInput) : null,
    ])

    if (!bearerToken) {
      // A session caller already produced a valid login JWT above, so a missing
      // bearer means jurisdictional token minting failed or the cell is
      // misconfigured — a server-side dependency failure, not an expired
      // session. Only the bearer/CLI path (a missing inbound token) is a 401.
      return isSessionCaller
        ? c.json({ error: "Unable to resolve authentication token for search" }, 502)
        : c.json({ error: "Unable to resolve authentication token for search" }, 401)
    }

    // Browser (session) callers send an "owner/repo" slug — resolve it to the
    // storage ULID query-serve expects. CLI/bearer callers already pass a ULID,
    // so forward theirs untouched.
    let repoParam = repoInput
    if (resolvedRepo) {
      if (resolvedRepo.kind === "not_found") {
        return c.json({ error: "Repo not found or not accessible" }, 404)
      }
      if (resolvedRepo.kind === "unavailable") {
        return c.json({ error: "Unable to resolve repo for search" }, 502)
      }
      repoParam = resolvedRepo.ulid
    }

    const url = new URL(
      "/api/v1/semantic-search/search/v1/search",
      c.env.ENTIRE_API_SEARCH_BASE_URL,
    )
    url.searchParams.set("repo", repoParam)
    for (const key of FORWARDED_PARAMS) {
      const value = c.req.query(key)
      if (value !== undefined) {
        url.searchParams.set(key, value)
      }

