package cli

import (
	"context"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/internal/coreapi"
)

// cellResolveTimeout bounds the best-effort control-plane lookups that
// pick a repo's cell. Without it, a reachable-but-hung control plane would block
// the calling command (experts, and any future cell-routed command) instead of
// degrading to home-jurisdiction routing — the "any failure falls back" contract
// must hold for slow cores, not just erroring ones.
const cellResolveTimeout = 5 * time.Second

// cellCoreClient is the control-plane surface the cell-target resolver needs.
// An interface (with a swappable constructor) so the resolver is unit-testable
// against a fake control plane; *coreapi.Client satisfies it.
type cellCoreClient interface {
	GetRepo(ctx context.Context, params coreapi.GetRepoParams) (*coreapi.Repo, error)
	ListClusters(ctx context.Context) (*coreapi.ListClustersOutputBody, error)
	ListMirrors(ctx context.Context, params coreapi.ListMirrorsParams) (*coreapi.ListMirrorsOutputBody, error)
}

// newCellCoreClient builds the control-plane client used for cell resolution.
// Swapped in tests.
var newCellCoreClient = func() (cellCoreClient, error) { return coreapi.New() }

// resolveRepoCellTarget resolves the entire-api cell that HOSTS the given
// repo, plus that cell's jurisdiction, so a repo-scoped call (experts today)
// reaches the region that owns the repo — mirroring how the entire.io BFF
// selects a cell per repo (resolve-cluster-host.ts / repos-stream.ts) rather
// than using the caller's home cell.
//
// It is deliberately best-effort: ANY failure (not logged in, control-plane
// error or timeout, unknown/ambiguous placement, missing apiUrl) returns nil,
// and the auth-layer client falls back to home-jurisdiction routing. That
// fallback is exactly the previous behaviour, so this can never regress the
// common same-region case (where the repo's jurisdiction equals the caller's
// home). A short deadline keeps a slow control plane from stalling the command.
//
// Placement source:
//   - ulid form: coreapi.GetRepo(ulid) -> Repo.ClusterHost;
//   - owner/repo form: coreapi mirrors filtered to this repo -> ClusterHost.
//
// The cluster host is then mapped to a cell apiUrl + jurisdiction via the
// coreapi cluster catalog (ListClusters), the authoritative source for a
// jurisdiction's cell URL.
func resolveRepoCellTarget(ctx context.Context, fullName, ulid string) *auth.CellTarget {
	ctx, cancel := context.WithTimeout(ctx, cellResolveTimeout)
	defer cancel()

	c, err := newCellCoreClient()
	if err != nil {
		logging.Debug(ctx, "cell target: core client unavailable, using home-jurisdiction routing", "error", err.Error())
		return nil
	}

	clusterHost, ok := resolveRepoClusterHost(ctx, c, fullName, ulid)
	if !ok || clusterHost == "" {
		return nil
	}

	clusters, err := c.ListClusters(ctx)
	if err != nil {
		logging.Debug(ctx, "cell target: list clusters failed, using home-jurisdiction routing", "error", err.Error())
		return nil
	}
	cluster, ok := matchClusterByHost(clusters.Clusters, clusterHost)
	if !ok {
		logging.Debug(ctx, "cell target: no cluster matched repo host, using home-jurisdiction routing", "cluster_host", clusterHost)
		return nil
	}
	apiURL := strings.TrimRight(strings.TrimSpace(cluster.ApiUrl.Or("")), "/")
	// DNS is case-insensitive; normalise the catalog jurisdiction so a
	// non-lowercase value still passes the auth layer's strict label check
	// instead of hard-failing the target path.
	jurisdiction := strings.ToLower(strings.TrimSpace(cluster.Jurisdiction))
	if apiURL == "" || jurisdiction == "" {
		logging.Debug(ctx, "cell target: matched cluster missing apiUrl/jurisdiction, using home-jurisdiction routing", "cluster_host", clusterHost)
		return nil
	}
	return &auth.CellTarget{BaseURL: apiURL, Jurisdiction: jurisdiction}
}

// resolveRepoClusterHost finds the public cluster host that owns the repo. It
// returns ok=false to signal "fall back to home-jurisdiction routing" for every
// unresolved or ambiguous case, never an error.
func resolveRepoClusterHost(ctx context.Context, c cellCoreClient, fullName, ulid string) (string, bool) {
	if strings.TrimSpace(ulid) != "" {
		repo, err := c.GetRepo(ctx, coreapi.GetRepoParams{RepoId: ulid})
		if err != nil {
			logging.Debug(ctx, "cell target: GetRepo failed, using home-jurisdiction routing", "error", err.Error())
			return "", false
		}
		return strings.TrimSpace(repo.ClusterHost.Or("")), true
	}

	owner, repo, ok := strings.Cut(strings.TrimSpace(fullName), "/")
	if !ok || owner == "" || repo == "" {
		return "", false
	}
	mirrors, err := listMirrorsForRepo(ctx, c, mirrorCloneProviderGitHub, strings.ToLower(owner), strings.ToLower(repo))
	if err != nil {
		logging.Debug(ctx, "cell target: list mirrors failed, using home-jurisdiction routing", "error", err.Error())
		return "", false
	}
	hosts := distinctActiveClusterHosts(mirrors)
	if len(hosts) != 1 {
		// Zero placements (not mirrored / unknown) or multiple regions
		// (ambiguous which cell holds the repo-scoped data): fall back rather than
		// guess a region.
		if len(hosts) > 1 {
			logging.Debug(ctx, "cell target: repo mirrored in multiple regions, using home-jurisdiction routing", "count", len(hosts))
		}
		return "", false
	}
	return hosts[0], true
}

// isActiveMirror reports whether a mirror placement can currently serve the
// repo: not archived, and not in a failed/suspended clone state. An unset status
// is treated as active (older data). Shared by every caller that must ignore
// placements a cell can't answer for.
func isActiveMirror(m coreapi.Mirror) bool {
	if m.IsArchived.Or(false) {
		return false
	}
	st := m.Status.Or(coreapi.MirrorStatusReady)
	return st != coreapi.MirrorStatusFailed && st != coreapi.MirrorStatusSuspended
}

// distinctActiveClusterHosts returns the set of cluster hosts a repo is actively
// serviced on: excluding archived placements and unhealthy ones (failed /
// suspended clone status), since those cells can't answer for the repo.
// A failed/suspended placement must neither manufacture false cross-region
// ambiguity nor become a sole "active" host. Case-folded to match DNS
// semantics; order is unimportant (callers only use a single-member set).
func distinctActiveClusterHosts(mirrors []coreapi.Mirror) []string {
	seen := make(map[string]string, len(mirrors))
	for _, m := range mirrors {
		if !isActiveMirror(m) {
			continue
		}
		host := strings.TrimSpace(m.ClusterHost)
		if host == "" {
			continue
		}
		key := strings.ToLower(host)
		if _, ok := seen[key]; !ok {
			seen[key] = host
		}
	}
	out := make([]string, 0, len(seen))
	for _, host := range seen {
		out = append(out, host)
	}
	return out
}

// matchClusterByHost finds the catalog cluster whose public host equals
// clusterHost (case-insensitive). The cluster's apiUrl + jurisdiction are the
// authoritative cell coordinates.
func matchClusterByHost(clusters []coreapi.Cluster, clusterHost string) (coreapi.Cluster, bool) {
	want := strings.ToLower(strings.TrimSpace(clusterHost))
	if want == "" {
		return coreapi.Cluster{}, false
	}
	for _, cl := range clusters {
		host, err := hostFromPublicURL(cl.PublicUrl)
		if err != nil {
			continue
		}
		if strings.EqualFold(strings.TrimSpace(host), want) {
			return cl, true
		}
	}
	return coreapi.Cluster{}, false
}

package auth

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"regexp"
	"strings"
	"sync"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/internal/entireclient/clusterdiscovery"
	"github.com/entireio/cli/internal/entireclient/httputil"
	"github.com/entireio/cli/internal/entireclient/userdirs"
)

const (
	cellDataAPITimeout = 30 * time.Second

	// JurisdictionIdentityScope is the scope jurisdiction identity tokens
	// are minted with (also used by git-remote-entire's jurisdiction git
	// auth). The receiving surface authorizes live per request, so the
	// scope carries identity semantics only, not a permission grant.
	JurisdictionIdentityScope = "openid"

	// clustersAPIPath is entire-core's cluster catalog endpoint.
	clustersAPIPath = "/api/v1/clusters"
)

// jurisdictionLabelPattern bounds a home_jurisdiction claim to a single DNS
// label before it is substituted into a URL template. The claim rides on the
// login JWT (which we decode without verifying the signature) and, for the
// home-jurisdiction fallback path, is attacker-influenceable if a token is ever
// mis-minted; constraining it to [a-z0-9-] means it can only ever name a
// sibling jurisdiction, never inject host/scheme syntax (e.g.
// "us.auth.evil.tld") into jurisdictionAudience / jurisdictionCoreURL.
var jurisdictionLabelPattern = regexp.MustCompile(`^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$`)

// CellTarget pins the entire-api cell a repo-scoped call must reach and the
// jurisdiction its identity token must be minted for. The cli layer resolves it
// from the repo's own cluster (via coreapi mirrors/clusters), so a repo-scoped
// route reaches the cell that HOSTS the repo — not the caller's home cell. A nil
// target falls back to home-jurisdiction routing (derived from the login JWT),
// which is correct for the common same-region case and for local dev.
type CellTarget struct {
	// BaseURL is the cell's apiUrl to dial (e.g. https://aws-eu-west-1.api.entire.io).
	BaseURL string
	// Jurisdiction is the repo's cluster jurisdiction; it drives the identity
	// token's audience and the core the exchange is performed at.
	Jurisdiction string
}

// resolveContextForCellAPI is the discovery seam for cell routing, swapped in
// tests. Mirrors resolveContextForAPI.
var resolveContextForCellAPI resolveContextFunc = clusterdiscovery.ResolveContextForAPI

// SetResolveContextForCellAPIForTest overrides the cell-API discovery seam.
func SetResolveContextForCellAPIForTest(t interface{ Helper() }, fn resolveContextFunc) func() {
	t.Helper()
	prev := resolveContextForCellAPI
	resolveContextForCellAPI = fn
	return func() { resolveContextForCellAPI = prev }
}

// cellExchangeTransportForTest, when non-nil, is the HTTP transport used for
// jurisdiction token exchange and cluster listing. Production leaves it nil.
var cellExchangeTransportForTest http.RoundTripper

// SetCellExchangeTransportForTest overrides the transport used for jurisdiction
// token exchange and cluster listing, returning a restore closure — the same
// set/restore convention the rest of the package uses for test seams.
func SetCellExchangeTransportForTest(t interface{ Helper() }, rt http.RoundTripper) func() {
	t.Helper()
	prev := cellExchangeTransportForTest
	cellExchangeTransportForTest = rt
	return func() { cellExchangeTransportForTest = prev }
}

// NewEntireAPICellClient returns an authenticated client aimed at an entire-api
// cell, carrying a jurisdictional identity token (scope=openid, aud=jurisdiction
// host). Repo-scoped entire-api routes do not accept the narrowed api-access
// bearer minted for the BFF origin — they require a cell identity token
// (COR-666).
//
// Cell selection, in precedence order:
//   - target != nil: dial target.BaseURL and mint for target.Jurisdiction. This
//     is the repo-scoped path — the caller (cli) resolved the repo's own cell.
//   - the configured data host already targets a cell (host contains ".api."):
//     keep that origin.
//   - a loopback data host (local dev): keep that origin.
//   - otherwise the data host is a BFF/apex: resolve the caller's home-cell
//     apiUrl from the cluster catalog (home-jurisdiction fallback).
func NewEntireAPICellClient(ctx context.Context, insecureHTTP bool, target *CellTarget) (*api.Client, error) {
	factory, err := NewEntireAPICellClientFactory(ctx, insecureHTTP)
	if err != nil {
		return nil, err
	}
	return factory.ClientFor(ctx, target)
}

// CellClientFactory builds entire-api cell clients from a single resolved
// exchange subject, minting at most one jurisdictional identity token per
// jurisdiction. Identity tokens are per-jurisdiction, not per-cell — every cell
// in a jurisdiction accepts the same token — so a caller dialing several cells
// in one operation (multi-cell fan-out over the caller's repos) should build
// one factory and reuse it for every cell, instead of paying discovery + login
// refresh + RFC 8693 exchange once per cell via NewEntireAPICellClient.
//
// A factory is safe for concurrent use, and holds credentials resolved at
// construction time — build it per operation, don't store it long-term. Like
// NewEntireAPICellClient it deliberately does NOT consult ENTIRE_TOKEN.
type CellClientFactory struct {
	subject cellSubject

	// mu guards the slots map only and is never held across I/O; the
	// hold-across-I/O locking is per-jurisdiction, on each mintSlot.mu.
	mu    sync.Mutex
	slots map[string]*mintSlot // jurisdiction -> its token slot
}

// mintSlot single-flights one jurisdiction's token. Unlike the factory-level
// mutex, the slot mutex IS deliberately held across the network exchange:
// concurrent callers for the same jurisdiction wait for one mint instead of
// duplicating it, while other jurisdictions mint in parallel on their own
// slots. A failed mint caches nothing — the next caller retries.
type mintSlot struct {
	mu    sync.Mutex
	token string
}

// NewEntireAPICellClientFactory resolves the exchange subject (active stored
// login context) once, for building clients aimed at several cells. See
// NewEntireAPICellClient for the single-cell convenience wrapper.

package auth

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"net/url"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/internal/entireclient/clusterdiscovery"
	"github.com/entireio/cli/internal/entireclient/contexts"
	"github.com/entireio/cli/internal/entireclient/userdirs"
)

// dataAPIDiscoveryTimeout bounds the one /.well-known/entire-api.json GET we
// add per data-API command. Kept short so a slow or absent endpoint fails the
// command promptly rather than stalling it.
const dataAPIDiscoveryTimeout = 8 * time.Second

// resolveContextFunc is the shape of a context-discovery seam: it mirrors
// clusterdiscovery.ResolveContextForAPI / ResolveContextForCluster
// (ctx, configDir, cacheDir, host, httpClient, debugf).
type resolveContextFunc func(context.Context, string, string, string, *http.Client, clusterdiscovery.DebugFunc) (*contexts.Context, error)

// resolveContextForAPI is the discovery seam, swapped in tests so they don't
// reach the network. See SetResolveContextForAPIForTest for cross-package tests.
var resolveContextForAPI resolveContextFunc = clusterdiscovery.ResolveContextForAPI

// SetResolveContextForAPIForTest overrides the /.well-known/entire-api.json
// discovery seam and returns a cleanup func. Tests in other packages that
// exercise a data-API command (activity/search/dispatch/recap) MUST install
// this — otherwise ResolveDataAPIToken makes a real network call to the
// configured data host. Test-only.
func SetResolveContextForAPIForTest(t interface{ Helper() }, fn resolveContextFunc) func() {
	t.Helper()
	prev := resolveContextForAPI
	resolveContextForAPI = fn
	return func() { resolveContextForAPI = prev }
}

// ResolveDataAPIToken returns a bearer for the data API at dataBaseURL.
//
// It dials the API's /.well-known/entire-api.json to learn which login
// server(s) the API trusts and which audience to exchange for, picks the
// matching local auth context (active-wins-if-eligible → sole → explicit
// choice), and exchanges that context's login JWT for the advertised audience
// at that context's core. This is what makes
//
//	ENTIRE_API_BASE_URL=https://partial.to entire activity
//
// authenticate as the partial.to login even while the active context is a
// prod entire.io login — with no per-command override needed.
//
// Discovery is the only path: an API host that doesn't advertise
// /.well-known/entire-api.json (unreachable / 404 / 503 / malformed) is an
// error — without it we can't know which login servers the host trusts, and
// guessing risks exchanging a token at a core the host doesn't accept.
//
// Callers that honour --insecure-http-auth must call EnableInsecureHTTP before
// invoking this (as they already do); the per-context exchange reads that
// global opt-in.
func ResolveDataAPIToken(ctx context.Context, dataBaseURL string) (string, error) {
	dataOrigin := api.OriginOnly(dataBaseURL)
	host, ok := hostOf(dataOrigin)
	if !ok {
		return "", fmt.Errorf("data API URL %q has no host to discover against", dataBaseURL)
	}

	dctx, cancel := context.WithTimeout(ctx, dataAPIDiscoveryTimeout)
	defer cancel()
	httpClient := dataAPIDiscoveryClient(dataOrigin)

	selected, err := resolveContextForAPI(dctx, userdirs.Config(), userdirs.Cache(), host, httpClient, nil)
	if errors.Is(err, clusterdiscovery.ErrDiscoveryUnavailable) {
		return "", fmt.Errorf("%s does not advertise its trusted login servers (/.well-known/entire-api.json missing or unreachable); cannot authenticate: %w", host, err)
	}
	if err != nil {
		return "", err
	}

	// Exchange for the data host origin; the token manager derives the RFC 8693
	// audience from it, which is the aud the API requires (aud == base URI).
	allowInsecure := insecureHTTPEnabled() || isLoopbackHTTP(selected.CoreURL)
	provider, err := NewRefreshingResourceProvider(selected, dataOrigin, nil, allowInsecure)
	if err != nil {
		return "", err
	}
	return provider(ctx)
}

type dataAPIHTTPDiscoveryTransport struct {
	base http.RoundTripper
}

func (t dataAPIHTTPDiscoveryTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	clone := req.Clone(req.Context())
	clone.URL.Scheme = schemeHTTP
	resp, err := t.base.RoundTrip(clone)
	if err != nil {
		return nil, fmt.Errorf("plain HTTP data API discovery: %w", err)
	}
	return resp, nil
}

func dataAPIDiscoveryClient(dataOrigin string) *http.Client {
	client := &http.Client{Timeout: dataAPIDiscoveryTimeout}
	if !shouldUsePlainHTTPDiscovery(dataOrigin) {
		return client
	}

	var base http.RoundTripper
	base = http.DefaultTransport
	if client.Transport != nil {
		base = client.Transport
	}
	client.Transport = dataAPIHTTPDiscoveryTransport{base: base}
	return client
}

package cli

import (
	"context"
	"errors"
	"io"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/internal/coreapi"
)

// currentRepoRefTimeout bounds currentRepoRef's control-plane lookup. The
// lookup is best-effort decoration (recap degrades to personal-only without
// it), so a stalled core must not hang the command — mirror cellResolveTimeout.
const currentRepoRefTimeout = 5 * time.Second

// runAuthenticatedActivityAPI runs fn with an authenticated client for the
// activity/recap surface. It prefers the caller's home entire-api cell (the same
// shared client the experts commands use), which serves the /me/* endpoints
// these commands call.
//
// Cell routing is a best-effort upgrade: any failure building the cell client —
// the region has no cell yet (ErrNoCellForJurisdiction), not logged in, or a
// discovery/exchange error — falls back to the data API, which also serves
// /me/* and yields the canonical auth errors (e.g. the "not logged in" hint).
// This keeps the migration transparent and non-regressive; non-obvious
// fallbacks are logged for diagnosis. Both backends expose the same /me/* paths,
// so fn is agnostic to which client it receives.
func runAuthenticatedActivityAPI(ctx context.Context, errW io.Writer, insecureHTTP bool, fn func(context.Context, *api.Client) error) error {
	client, err := auth.NewEntireAPICellClient(ctx, insecureHTTP, nil)
	if err != nil {
		logCellClientFallback(ctx, err)
		return runAuthenticatedDataAPI(ctx, errW, insecureHTTP, fn)
	}
	return fn(ctx, client)
}

// logCellClientFallback records, at debug, that an activity/recap command fell
// back from the entire-api cell to the data API. The expected cases — the
// region has no cell yet, or the caller isn't logged in — aren't logged: they
// are normal during rollout and on first use, not diagnosable failures.
func logCellClientFallback(ctx context.Context, err error) {
	if errors.Is(err, auth.ErrNoCellForJurisdiction) || errors.Is(err, auth.ErrNotLoggedIn) {
		return
	}
	logging.Debug(ctx, "activity/recap: entire-api cell client unavailable, using data API", "error", err.Error())
}

// forgeToMirrorProvider maps a gitremote forge identifier (e.g. "gh") to the
// upstream provider the control plane records mirrors under (e.g. "github").
// entire-api routing only supports GitHub mirrors today.
func forgeToMirrorProvider(forge string) (string, bool) {
	switch strings.ToLower(strings.TrimSpace(forge)) {
	case "gh", mirrorCloneProviderGitHub:
		return mirrorCloneProviderGitHub, true
	default:
		return "", false
	}
}

// currentRepoRef best-effort resolves the current repo (its "origin" remote)
// to the ULID entire-api uses for repo-scoped params — recap's /me/recap?repo=
// — plus the human owner/repo slug for display, from a single remote
// resolution (the caller needs both; resolving twice would double the git and
// control-plane work). entire.io/api documents the mirror id as exactly that
// repo_id (repo_id = mirror_repos.id), and the CLI already lists mirrors via
// the control plane, so no extra resolution is needed. Any failure returns
// "", "" — recap then shows the personal side only rather than erroring.
func currentRepoRef(ctx context.Context) (repoID, repoSlug string) {
	ctx, cancel := context.WithTimeout(ctx, currentRepoRefTimeout)
	defer cancel()

	forge, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
	if err != nil || owner == "" || repo == "" {
		return "", ""
	}
	provider, ok := forgeToMirrorProvider(forge)
	if !ok {
		return "", ""
	}
	c, err := coreapi.New()
	if err != nil {
		return "", ""
	}
	mirrors, err := listMirrorsForRepo(ctx, c, provider, strings.ToLower(owner), repo)
	if err != nil {
		return "", ""
	}
	repoID = firstActiveRepoID(mirrors)
	if repoID == "" {
		return "", ""
	}
	return repoID, owner + "/" + repo
}

// firstActiveRepoID returns the id of the repo's first active mirror (the repo
// id is stable across a repo's placements, so any active one serves). Archived
// and failed/suspended placements are skipped — they can't answer for the repo.
func firstActiveRepoID(mirrors []coreapi.Mirror) string {
	for i := range mirrors {
		if !isActiveMirror(mirrors[i]) {
			continue
		}
		if id := strings.TrimSpace(mirrors[i].MirrorId); id != "" {
			return id
		}
	}
	return ""
}

